// CreateTableWithDBType creates the Project_Ledger_Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *ProjectLedgerEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ProjectLedgerEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetProjectLedgerEntryPostgresTableSchema()
	} else {
		schema = GetProjectLedgerEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Project_Ledger_Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *ProjectLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, ProjectLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (project_no, posting_date)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$project_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index project_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (project_no, open, positive, posting_date)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$project_open", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index project_open: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (project_no, entry_type, type, project_posting_group)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$project_entry_type", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index project_entry_type: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (applies_to_id)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$applies_to_id", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index applies_to_id: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (closed_by_entry_no)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$closed_by_entry_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index closed_by_entry_no: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (related_to_budget, project_no, entry_type, phase_code, task_code, step_code, type, no, posting_date)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$budget_line_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index budget_line_date: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (project_no, entry_type, type, no, unit_of_measure_code, work_type_code)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$project_type_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index project_type_no: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (type, country_code, source_code, posting_date)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$type_country", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_country: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Project_Ledger_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	var keys []sift.Key
	for _, spec := range projectLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ProjectLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ProjectLedgerEntryTableName, keys)
}

// projectLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func projectLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "budget_line_date",
			Fields: []sift.Column{{Name: "related_to_budget", Kind: sift.KindBool}, {Name: "project_no", Kind: sift.KindText}, {Name: "entry_type", Kind: sift.KindInt}, {Name: "phase_code", Kind: sift.KindText}, {Name: "task_code", Kind: sift.KindText}, {Name: "step_code", Kind: sift.KindText}, {Name: "type", Kind: sift.KindInt}, {Name: "no", Kind: sift.KindText}, {Name: "posting_date", Kind: sift.KindDate}},
			Sums:   []sift.Column{{Name: "total_cost", Kind: sift.KindDecimal}, {Name: "total_price", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *ProjectLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, ProjectLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range projectLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ProjectLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ProjectLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ProjectLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

